"use client";

import React from "react";

import LetterSwapForward from "@/components/LetterHover";
import { RandomLetterSwapPingPong } from "@/components/RandomLetterSwapHover";

export default function Example() {
	return (
		<div className="h-screen w-full flex items-center justify-center relative overflow-hidden bg-black">
			<div className="w-dvw h-dvh rounded-lg bg-white text-xl md:text-3xl  flex flex-col items-center justify-center font-calendas">
				<div className=" p-12 text-[#0015ff] rounded-xl align-text-top  gap-y-1 md:gap-y-2 flex flex-col">
					<LetterSwapForward
						label="Hover me chief!"
						reverse={true}
						className="italic"
					/>
					<LetterSwapForward
						label="{awesome}"
						reverse={false}
						className="font-bold"
					/>
					<LetterSwapForward
						label="Good day!"
						staggerFrom={"center"}
						className="mono"
					/>
					<RandomLetterSwapPingPong
						label="More text?"
						staggerFrom={"center"}
						reverse={false}
						className="font-overused-grotesk font-bold"
					/>
					<RandomLetterSwapPingPong
						label="oh, seriously?!"
						staggerFrom={"last"}
					/>
				</div>
			</div>{" "}
		</div>
	);
}

"use client";

import { useState } from "react";

import {
	DynamicAnimationOptions,
	motion,
	stagger,
	useAnimate,
} from "motion/react";

// Credit:
// https://www.fancycomponents.dev/docs/components/text/letter-swap

interface TextProps {
	label: string;
	reverse?: boolean;
	transition?: DynamicAnimationOptions;
	staggerDuration?: number;
	staggerFrom?: "first" | "last" | "center" | number;
	className?: string;
	onClick?: () => void;
}

const LetterSwapForward = ({
	label,
	reverse = true,
	transition = {
		type: "spring",
		duration: 0.7,
	},
	staggerDuration = 0.03,
	staggerFrom = "first",
	className,
	onClick,
	...props
}: TextProps) => {
	const [scope, animate] = useAnimate();
	const [blocked, setBlocked] = useState(false);

	const hoverStart = () => {
		if (blocked) return;

		setBlocked(true);

		// Function to merge user transition with stagger and delay
		const mergeTransition = (baseTransition: DynamicAnimationOptions) => ({
			...baseTransition,
			delay: stagger(staggerDuration, {
				from: staggerFrom,
			}),
		});

		animate(
			".letter",
			{ y: reverse ? "100%" : "-100%" },
			mergeTransition(transition)
		).then(() => {
			animate(
				".letter",
				{
					y: 0,
				},
				{
					duration: 0,
				}
			).then(() => {
				setBlocked(false);
			});
		});

		animate(
			".letter-secondary",
			{
				top: "0%",
			},
			mergeTransition(transition)
		).then(() => {
			animate(
				".letter-secondary",
				{
					top: reverse ? "-100%" : "100%",
				},
				{
					duration: 0,
				}
			);
		});
	};

	return (
		<span
			className={`flex justify-center items-center relative overflow-hidden  ${className} `}
			onMouseEnter={hoverStart}
			onClick={onClick}
			ref={scope}
			{...props}
		>
			<span className="sr-only">{label}</span>

			{label.split("").map((letter: string, i: number) => {
				return (
					<span
						className="whitespace-pre relative flex"
						key={i + "letter-hover"}
					>
						<motion.span className={`relative letter`} style={{ top: 0 }}>
							{letter}
						</motion.span>
						<motion.span
							className="absolute letter-secondary "
							aria-hidden={true}
							style={{ top: reverse ? "-100%" : "100%" }}
						>
							{letter}
						</motion.span>
					</span>
				);
			})}
		</span>
	);
};

export default LetterSwapForward;
